import { remainingRange } from "@/lib/progress";
import { describe, it, expect, vi } from "vitest";
import Papa from "papaparse";
import { encryptToken, decryptToken } from "@/lib/crypto";
import {
  renderTemplate,
  templateSchema,
  campaignSchema,
  validatePdf,
  MAX_PDF_BYTES,
  preferredRolesSchema,
} from "@/lib/validation";
import { parseContacts, suggestName, validateImportRows } from "@/lib/imports";

describe("refresh token encryption", () => {
  const owner = "11111111-1111-4111-8111-111111111111";
  process.env.TOKEN_ENCRYPTION_KEY = "ab".repeat(32);
  process.env.TOKEN_ENCRYPTION_ACTIVE_KEY_ID = "test";
  process.env.TOKEN_ENCRYPTION_ACTIVE_KEY = "cd".repeat(32);
  it("round-trips with a fresh nonce and rejects tampering", () => {
    const encrypted = encryptToken("secret-refresh-token", owner);
    expect(decryptToken(encrypted, owner)).toBe("secret-refresh-token");
    expect(encryptToken("secret-refresh-token", owner)).not.toBe(encrypted);
    const parts = encrypted.split(".");
    parts[3] = Buffer.from("tampered").toString("base64url");
    expect(() => decryptToken(parts.join("."), owner)).toThrow();
  });
});
describe("template and contact validation", () => {
  it("renders literal replacement values safely", () => {
    expect(
      renderTemplate("Hi {{ name }}, {{company}} / {{role}}", {
        name: "$&",
        company: null,
        role: "Engineer",
      }),
    ).toBe("Hi $&,  / Engineer");
  });
  it("rejects unknown placeholders and injected headers", () => {
    expect(
      templateSchema.safeParse({
        name: "Test",
        subject: "Hi\r\nBcc: [REDACTED_EMAIL]",
        body: "Hello",
      }).success,
    ).toBe(false);
    expect(
      templateSchema.safeParse({
        name: "Test",
        subject: "Hi",
        body: "{{unknown}}",
      }).success,
    ).toBe(false);
  });
  it("normalizes imports, handles quoted commas, flags duplicates and invalid emails", () => {
    const rows = parseContacts(
      'name,email,company,jobRole\nAlice, [REDACTED_EMAIL] ,"Example, Inc",Engineer\nA,[REDACTED_EMAIL],X,Engineer\nB,bad,X,Engineer',
    );
    expect(rows.map((r) => r.state)).toEqual(["valid", "duplicate", "invalid"]);
    expect(rows[0].company).toBe("Example, Inc");
    expect(
      parseContacts(
        "name\temail\tcompany\tjobRole\nA\[REDACTED_EMAIL]\tX\tEngineer",
        ["[REDACTED_EMAIL]"],
      )[0].state,
    ).toBe("duplicate");
  });
  it("rejects oversized imports and incomplete headers", () => {
    expect(() => parseContacts("x".repeat(1024 * 1024 + 1))).toThrow();
    expect(parseContacts("email\[REDACTED_EMAIL]")[0].state).toBe("invalid");
  });
  it.each([1001, 2000, 4000])(
    "stops malformed CSV at the first excess row for %i input rows",
    (count) => {
      const parse = Papa.parse;
      let parsedRows = 0;
      const spy = vi.spyOn(Papa, "parse").mockImplementation(((
        text: string,
        config: Papa.ParseConfig<Record<string, string>>,
      ) =>
        parse(text, {
          ...config,
          step: (result, parser) => {
            parsedRows++;
            config.step?.(result, parser);
          },
        })) as typeof Papa.parse);
      try {
        expect(() =>
          parseContacts("email,name,role\n" + "x,x\n".repeat(count)),
        ).toThrow("Import at most 1,000 rows at a time.");
        expect(parsedRows).toBe(1001);
      } finally {
        spy.mockRestore();
      }
    },
  );
  it("accepts 1,000 CSV records with empty lines and quoted newlines", () => {
    const rows = parseContacts(
      "email,name,role,company\n" +
        Array.from(
          { length: 1000 },
          (_, i) => `person${i}@example.com,Alex,Engineer,"Example\nCompany"`,
        ).join("\n\n"),
    );
    expect(rows).toHaveLength(1000);
    expect(rows.every((row) => row.state === "valid")).toBe(true);
    expect(rows[0].company).toBe("Example\nCompany");
  });
  it("flags only the malformed CSV record without scanning errors from other rows", () => {
    const rows = parseContacts(
      "email,name,role\[REDACTED_EMAIL],Alice,Engineer\[REDACTED_EMAIL],Bob\[REDACTED_EMAIL],Carol,Engineer",
      [],
      "Engineer",
    );
    expect(rows.map((row) => row.state)).toEqual(["valid", "invalid", "valid"]);
    expect(rows[1].error).toBe("Check the number of columns.");
  });
  it("bounds plain email lists while ignoring blank entries", () => {
    const emails = Array.from(
      { length: 1000 },
      (_, i) => `alex${i}@example.com`,
    );
    expect(parseContacts(emails.join("; ;\n"), [], "Engineer")).toHaveLength(
      1000,
    );
    expect(() =>
      parseContacts([...emails, "[REDACTED_EMAIL]"].join(","), [], "Engineer"),
    ).toThrow("Import at most 1,000 rows at a time.");
  });
  it("rejects 11 recipients and non-PDF files", () => {
    expect(
      campaignSchema.safeParse({
        templateId: crypto.randomUUID(),
        idempotencyKey: crypto.randomUUID(),
        recipientIds: Array.from({ length: 11 }, () => crypto.randomUUID()),
        attachResume: false,
      }).success,
    ).toBe(false);
    expect(
      campaignSchema.safeParse({
        templateId: crypto.randomUUID(),
        idempotencyKey: crypto.randomUUID(),
        recipientIds: Array.from({ length: 10 }, () => crypto.randomUUID()),
        attachResume: false,
      }).success,
    ).toBe(true);
    expect(() =>
      validatePdf(Buffer.from("not a pdf"), "application/pdf"),
    ).toThrow();
    expect(() =>
      validatePdf(Buffer.alloc(MAX_PDF_BYTES + 1), "application/pdf"),
    ).toThrow();
  });
});

describe("outreach preferences and email lists", () => {
  it("suggests editable first names conservatively", () => {
    expect(suggestName("[REDACTED_EMAIL]")).toBe("Alex");
    expect(suggestName("[REDACTED_EMAIL]")).toBe("Sam");
    expect(suggestName("[REDACTED_EMAIL]")).toBe("Test");
    for (const value of ["careers", "hr", "info", "x", "1234"])
      expect(suggestName(value + "@example.com")).toBe("");
  });
  it("parses lists, validates unresolved names and roles, and deduplicates", () => {
    const rows = parseContacts(
      "[REDACTED_EMAIL]; [REDACTED_EMAIL],[REDACTED_EMAIL]\[REDACTED_EMAIL]",
      [],
      "Engineer",
    );
    expect(rows.map((r) => r.state)).toEqual([
      "valid",
      "valid",
      "duplicate",
      "invalid",
    ]);
    expect(rows[0].company).toBe("");
    const fixed = validateImportRows(
      rows.map((r) => ({ ...r, error: undefined, name: r.name || "Taylor" })),
    );
    expect(fixed[3].state).toBe("valid");
    expect(parseContacts("[REDACTED_EMAIL]")[0].state).toBe("invalid");
  });
  it("validates preference count, case-insensitive uniqueness", () => {
    for (const roles of [
      [""],
      ["Engineer", " engineer "],
      Array.from({ length: 21 }, (_, i) => `Role ${i}`),
    ])
      expect(preferredRolesSchema.safeParse(roles).success).toBe(false);
    expect(
      preferredRolesSchema.parse(
        Array.from({ length: 20 }, (_, i) => `Role ${i}`),
      ),
    ).toHaveLength(20);
    expect(preferredRolesSchema.parse([" SDE Intern "])).toEqual([
      "SDE Intern",
    ]);
  });
  it("rejects legacy links and preserves multiple literal URLs", () => {
    const body =
      "Hi {{name}},\n\nPortfolio: https://example.com/$&?a=1&b=2\nGitHub: https://github.com/user\nLinkedIn: https://linkedin.com/in/user\n\nThank you.";
    expect(
      templateSchema.parse({ name: "Links", subject: "Hi", body }).body,
    ).toBe(body);
    expect(
      templateSchema.parse({
        name: "Links",
        subject: "Hi",
        body: body.replace(/\n/g, "\r\n"),
      }).body,
    ).toBe(body);
    expect(renderTemplate(body, { name: "Alex", role: "Engineer" })).toBe(
      body.replace("{{name}}", "Alex"),
    );
    for (const token of [
      "{{link}}",
      "{{ link }}",
      "{{\nlink\t}}",
      "{{unknown}}",
    ]) {
      for (const field of ["subject", "body"]) {
        const parsed = templateSchema.safeParse({
          name: "Legacy",
          subject: "Hi",
          body: "Hi",
          [field]: token,
        });
        expect(parsed.success).toBe(false);
        if (!parsed.success && token.includes("link"))
          expect(parsed.error.issues.map((issue) => issue.message)).toContain(
            "Replace {{link}} with a URL directly in your message.",
          );
      }
      expect(renderTemplate(token, { name: "Alex", role: "Engineer" })).toBe(
        token,
      );
    }
  });
});

describe("approximate delivery estimates", () => {
  it("includes all outstanding jobs and the persisted next-send delay", () => {
    const now = Date.parse("2026-10-08T10:00:00Z");
    expect(remainingRange(4, "2026-10-08T10:02:00Z", now)).toEqual({
      min: 2,
      max: 3,
    });
    expect(remainingRange(0, null, now)).toBeNull();
    expect(remainingRange(1, null, now)).toEqual({ min: 1, max: 1 });
  });
});
